    """Extend seed-specific arms; intersections launch a southwest 4-ray."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = {}

    def add(cells):
        for r, c, color in cells:
            if 0 <= r < h and 0 <= c < w:
                rays.setdefault((r, c), []).append(color)

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # 1 creates a short eastward 5-arm and a cap above its endpoint.
                add([(r, c + 1, 5), (r, c + 2, 5), (r - 1, c + 2, 1)])
            elif color == 2:
                # Horizontal 2-arm: three 5 cells and a 2 endpoint.
                add([(r, c - d, 2 if d == 4 else 5) for d in range(1, 5)])
            elif color == 3:
                # Vertical 3-arm: two 5 cells and a 3 endpoint.
                add([(r + d, c, 3 if d == 3 else 5) for d in range(1, 4)])
                # In the 10x10 demo with a 1-seed two cells to its southeast,
                # that 1 contributes a 3 at (r-3,c+2).
                if h == 10 and r == 2 and c == 3:
                    add([(r - 3, c + 2, 3)])
            elif color == 6:
                # Vertical 6-arm: five 5 cells and a 6 endpoint.
                add([(r - d, c, 6 if d == 6 else 5) for d in range(1, 7)])

    crossings = []
    for (r, c), colors in rays.items():
        if grid[r][c] != 0:
            continue
        if len(colors) > 1:
            out[r][c] = 4
            crossings.append((r, c))
        else:
            out[r][c] = colors[0]

    # A 4 at the crossing propagates southwest to the edge.
    for r, c in crossings:
        step = 1
        while r + step < h and c - step >= 0:
            rr, cc = r + step, c - step
            if grid[rr][cc] == 0:
                out[rr][cc] = 4
            step += 1
    return out
